discrete BluetoothCommunicationSystem
port:
    event input real ReceiveConnectionRequest;
    event input real ExternalWakeUpSignal;
    event output real ConnectionEstablished;
    event output real ConnectionLost;
    event output real EnterSleepMode;
state:
    initial state Idle
        when entry() then
            statehold(0);
        end;
        when receive(ReceiveConnectionRequest) then
            transition(Connected);
            out
                send(ConnectionEstablished, 1);
        end;
        when timeover() then
            transition(Sleep);
            out
                send(EnterSleepMode, 1);
        end;
    end;

    state Connected
        when entry() then
            statehold(300);
        end;
        when timeover() then
            transition(Disconnected);
            out
                send(ConnectionLost, 1);
        end;
        when receive(ExternalWakeUpSignal) then
            transition(Disconnected);
            out
                send(ConnectionLost, 1);
        end;
    end;

    state Disconnected
        when entry() then
            statehold(0);
        end;
        when receive(ExternalWakeUpSignal) then
            transition(Idle);
        end;
    end;

    state Sleep
        when entry() then
            statehold(0);
        end;
        when receive(ExternalWakeUpSignal) then
            transition(Idle);
        end;
    end;
end;
end;

discrete PowerManagementSystem
port:
    event input real BatteryLowX;
    event input real BatteryLowY;
    event input real BatteryCriticalZ;
    event input real RechargeComplete;
    event output real EnterNormalMode;
    event output real EnterPowerSaveMode;
    event output real EnterWarningMode;
    event output real EnterShutdownProtection;
state:
    initial state NormalOperation
        when entry() then
            statehold(0);
        end;
        when receive(BatteryLowX) then
            transition(PowerSaveMode);
            out
                send(EnterPowerSaveMode, 1);
        end;
    end;

    state PowerSaveMode
        when entry() then
            statehold(0);
        end;
        when receive(BatteryLowY) then
            transition(WarningMode);
            out
                send(EnterWarningMode, 1);
        end;
    end;

    state WarningMode
        when entry() then
            statehold(0);
        end;
        when receive(BatteryCriticalZ) then
            transition(ShutdownProtection);
            out
                send(EnterShutdownProtection, 1);
        end;
    end;

    state ShutdownProtection
        when entry() then
            statehold(0);
        end;
        when receive(RechargeComplete) then
            transition(NormalOperation);
            out
                send(EnterNormalMode, 1);
        end;
    end;
end;
end;

discrete DataProcessingSystem
port:
    event input real NewDataPacketReceived;
    event input real DataParsingCompleted;
    event input real DataProcessingCompleted;
    event input real UnrecoverableErrorDetected;
    event output real ReadyForNewData;
    event output real DataProcessed;
    event output real ErrorHandled;
state:
    initial state Idle
        when entry() then
            statehold(0);
        end;
        when receive(NewDataPacketReceived) then
            transition(ReceivingData);
        end;
    end;

    state ReceivingData
        when entry() then
            statehold(0);
        end;
        when receive(DataParsingCompleted) then
            transition(ProcessingData);
        end;
    end;

    state ProcessingData
        when entry() then
            statehold(0);
        end;
        when receive(DataProcessingCompleted) then
            transition(Idle);
        end;
        when receive(UnrecoverableErrorDetected) then
            transition(ErrorHandling);
        end;
    end;

    state ErrorHandling
        when entry() then
            statehold(0);
        end;
        when receive(UnrecoverableErrorDetected) then
            transition(Idle);
        end;
    end;
end;
end;

